using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration _reporting = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();

        _reporting = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(chatClient));
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenario = await _reporting.CreateScenarioRunAsync(TestContext.Current!);

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you today?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);
        scenario.AssertAllNumericMetricsMeetOrExceedThreshold(threshold: 3.0f);
    }

    [TestMethod]
    public async Task Chat_answers_factual_question_relevantly()
    {
        await using var scenario = await _reporting.CreateScenarioRunAsync(TestContext.Current!);

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);
        scenario.AssertAllNumericMetricsMeetOrExceedThreshold(threshold: 3.0f);
    }

    [TestMethod]
    public async Task Chat_handles_followup_questions()
    {
        await using var scenario = await _reporting.CreateScenarioRunAsync(TestContext.Current!);

        var chatClient = _appHost.Services.GetRequiredService<IChatClient>();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about photosynthesis."),
            new(ChatRole.Assistant, "Photosynthesis is the process by which plants convert sunlight into energy."),
            new(ChatRole.User, "What role does chlorophyll play in that process?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await scenario.EvaluateAsync(messages, response);
        scenario.AssertAllNumericMetricsMeetOrExceedThreshold(threshold: 3.0f);
    }
}

